/**
 * Unit tests for CommandLineRunner.getDefaultExterns().
 * Note: Since the method accesses static resources via ClassLoader, 
 * testing the failure branches (null input or mismatching zip content) 
 * requires controlling the classpath/resource loading.
 */
public class CommandLineRunner_getDefaultExterns_TriageGen1Test {

    /**
     * Tests the successful retrieval of default externs.
     * This assumes that 'externs.zip' is present in the test resources 
     * and contains exactly the files specified in DEFAULT_EXTERNS_NAMES.
     */
    @Test
    public void getDefaultExterns_success() throws IOException {
        // This test relies on the actual presence of the resource in the classpath
        // to validate the logic of zip parsing and ordering.
        try {
            List<SourceFile> result = CommandLineRunner.getDefaultExterns();

            assertThat(result).isNotNull();
            // The number of files should match the hardcoded DEFAULT_EXTERNS_NAMES
            // We can't access DEFAULT_EXTERNS_NAMES directly if it's private, 
            // but we can verify the result is not empty.
            assertThat(result.size()).isGreaterThan(0);

            // Verify the prefix logic applied during zip processing
            for (SourceFile file : result) {
                assertThat(file.getSourceName()).startsWith("externs.zip//");
            }
        } catch (AssertionError | IllegalStateException e) {
            // If the environment doesn't have the specific zip structure, 
            // this test is environment-dependent.
            throw e;
        }
    }

